// Notchset model-selector 2.0.0 · https://notchset.dev/changelog
"use client";
import { Menu as Base } from "@base-ui/react/menu";
import { Check, ChevronDown, Lock } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/notchset/button";
import { Menu } from "@/components/ui/notchset/menu";
import { popupItem } from "@/lib/notchset/popup";

/*
 * Model selector: which model answers, named by what it's for. Up to four choices ("Fast", "Balanced", "Deep
 * thinking", "Long documents"), each with one line on when to pick it and the model's own name under it; no hidden
 * Auto. A choice that can't answer right now stays listed, disabled, with the reason ("Busy right now"). An assistant
 * that fixes its model shows it as set, with who set it, instead of a menu. Every reply then names what answered
 * (Message's model line), so a fallback is never silent.
 *
 * The host owns the choice and the shortcut that opens it (⌘⇧M in the template), through open and onOpenChange.
 */
type ModelChoice = {
  id: string;
  /** what it's for, the name a person reads: "Balanced" */
  purpose: string;
  /** when to pick it: "Most questions; thinks longer when it helps" */
  note: string;
  /** the model's own name: "Claude Sonnet 5.5" */
  name: string;
  /** why it can't answer right now; shown, and the choice is disabled */
  unavailable?: string | undefined;
};
type ModelSelectorProps = {
  choices: ModelChoice[];
  value: string;
  onValueChange: (id: string) => void;
  /** who fixed the model ("Support assistant"): no menu, the choice is said as set */
  lockedBy?: string | undefined;
  open?: boolean | undefined;
  onOpenChange?: ((open: boolean) => void) | undefined;
  className?: string | undefined;
};

function ModelSelector({ choices, value, onValueChange, lockedBy, open, onOpenChange, className }: ModelSelectorProps) {
  const current = choices.find((c) => c.id === value) ?? choices[0];
  if (!current) return null;
  if (lockedBy)
    return (
      <span data-slot="model-selector" data-locked="" className={cn("inline-flex h-[var(--ns-control-sm)] items-center gap-1.5 px-2 text-[length:var(--ns-text-small)] text-[var(--ns-ink-2)]", className)}>
        <Lock aria-hidden className="size-3" />
        {current.purpose}
        <span className="text-[var(--ns-ink-3)] max-[600px]:hidden">· set by {lockedBy}</span>
      </span>
    );
  return (
    <Menu
      open={open}
      onOpenChange={onOpenChange}
      className="w-[min(300px,calc(100vw-16px))]"
      trigger={
        <Button data-slot="model-selector" size="sm" variant="ghost" aria-label={`Model: ${current.purpose}. Change model`} aria-keyshortcuts="Meta+Shift+M Control+Shift+M" className={cn("text-[var(--ns-ink-2)]", className)}>
          {current.purpose}
          <ChevronDown aria-hidden />
        </Button>
      }
    >
      <Base.RadioGroup value={value} onValueChange={(v) => onValueChange(String(v))}>
        {choices.map((c) => (
          <Base.RadioItem key={c.id} value={c.id} disabled={!!c.unavailable} closeOnClick className={cn(popupItem, "items-start py-2 data-disabled:opacity-100 data-disabled:[&_span]:text-[var(--ns-ink-3)]")}>
            <span className="mt-[3px] grid size-3.5 shrink-0 place-items-center">
              <Base.RadioItemIndicator>
                <Check aria-hidden className="size-3.5" />
              </Base.RadioItemIndicator>
            </span>
            <span className="flex min-w-0 flex-1 flex-col gap-0.5">
              <span className="flex items-baseline justify-between gap-2">
                <span className="font-[number:var(--ns-weight-medium)] text-[var(--ns-ink)]">{c.purpose}</span>
                <span className="truncate text-[length:var(--ns-text-meta)] text-[var(--ns-ink-3)]">{c.name}</span>
              </span>
              <span className="text-[length:var(--ns-text-small)] whitespace-normal text-[var(--ns-ink-2)]">{c.unavailable ?? c.note}</span>
            </span>
          </Base.RadioItem>
        ))}
      </Base.RadioGroup>
    </Menu>
  );
}

export { ModelSelector, type ModelChoice, type ModelSelectorProps };

// Notchset model-selector 2.0.0 · https://notchset.dev/changelog
/*
 * The one popup surface every list that opens from a control uses (select, combobox, recipient picker, and
 * menus in batch 3): the prototype's .menu. It drops just below its control, and on a phone it becomes a
 * bottom sheet with a grab handle and finger-sized rows. Kept as class strings so each primitive's own parts
 * wear the same look.
 */

/** On the Positioner: above everything but dialogs; on a phone, pinned to the bottom edge as a sheet (above a tab bar
    when the app sets --ns-sheet-bottom to its height). */
export const popupPositioner =
  "z-50 outline-hidden max-[600px]:!fixed max-[600px]:!inset-x-2 max-[600px]:!top-auto max-[600px]:!bottom-[calc(var(--ns-sheet-bottom)+env(safe-area-inset-bottom,0px))] max-[600px]:!left-2 max-[600px]:!w-auto max-[600px]:!transform-none";

/** On the Popup. */
export const popupSurface =
  "min-w-[max(var(--anchor-width,0px),180px)] max-h-[min(420px,70vh,var(--available-height,70vh))] overflow-auto overscroll-contain rounded-[var(--ns-radius-lg)] bg-[var(--ns-raised)] p-[5px] text-[length:var(--ns-text-body)] text-[var(--ns-ink)] shadow-[0_0_0_1px_var(--ns-line),var(--ns-shadow-float)] outline-hidden origin-[var(--transform-origin)] " +
  "[animation:ns-menu-in_var(--ns-time-menu)_var(--ns-ease)] data-ending-style:opacity-0 data-ending-style:[transition:opacity_110ms_ease] " +
  "max-[600px]:w-auto max-[600px]:min-w-0 max-[600px]:max-h-[70dvh] max-[600px]:rounded-[var(--ns-radius-xl)] max-[600px]:px-1.5 max-[600px]:pt-3.5 max-[600px]:pb-1.5 max-[600px]:[animation:ns-sheet-up_var(--ns-time-panel)_var(--ns-ease-panel)] " +
  "max-[600px]:before:absolute max-[600px]:before:top-[5px] max-[600px]:before:left-1/2 max-[600px]:before:h-1 max-[600px]:before:w-9 max-[600px]:before:-translate-x-1/2 max-[600px]:before:rounded-full max-[600px]:before:bg-[var(--ns-line)] max-[600px]:before:content-['']";

/** On each item. Highlight (pointer or arrow keys) is the hover wash; the chosen item carries a check. */
export const popupItem =
  "flex w-full min-h-[var(--ns-menu-row)] cursor-default items-center gap-[9px] rounded-[7px] px-[9px] text-left outline-hidden select-none data-highlighted:bg-[var(--ns-hover)] data-disabled:opacity-45 [&_svg:not([data-slot=company-mark])]:size-3.5 [&_svg]:shrink-0";

/** The quiet line a list shows when nothing matches. */
export const popupEmpty = "px-[9px] py-2 text-[length:var(--ns-text-small)] text-[var(--ns-ink-3)] empty:hidden";
